<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Scopes\Application\Usecase\ScopesConsentUsecase;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\ScopePermission;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

class ScopesConsentForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly ScopesConsentUsecase $scopesConsent,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer
    ) {
    }

    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $username = $input->challenges->username ?? '';
        $clientId = $input->authRequest->client->id;
        $clientName = $clientId;

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign")
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get('scopes.title');
        $help = $translator->get('scopes.help');
        $requiredTitle = $translator->get('scopes.required-title');
        $optionalTitle = $translator->get('scopes.optional-title');
        $send = $translator->get('scopes.send');

        $backLabel = $translator->get('scopes.back-label');
        $backText = $translator->get(
            'scopes.back-text',
            ["<input class=\"inline\" type=\"submit\" value=\"" . $backLabel . "\" />"]
        );

        $errorMessage = $error?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get('scopes.error-format', [$translator->get('error.' . strtolower($errorMessage))])
            : '';
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';

        $pending = $this->scopesConsent->pendingScopes($tenant, $username, $clientId, $input->authRequest->scope);
        [$required, $optional] = $this->splitScopes($pending);

        $requiredBlock = $required ? $this->renderRequiredBlock($requiredTitle, $required) : '';
        $optionalBlock = $optional ? $this->renderOptionalBlock($optionalTitle, $optional) : '';
        $separator = ($required && $optional) ? '<div class="scopes-separator" role="presentation"></div>' : '';
        $empty = (!$required && !$optional) ? '<p>' . $translator->get('scopes.empty') . '</p>' : '';

        $step = StepName::SCOPES_CONSENT->value;
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $input->request,
                'ScopesConsent',
                $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    <p><strong>Aplicacion:</strong> {$clientName}</p>
                    {$error}
                    {$empty}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <div class="scopes-scroll" style="max-height: 320px; overflow-y: auto; padding: 0.25rem 0;">
                            {$requiredBlock}
                            {$separator}
                            {$optionalBlock}
                        </div>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                    HTML,
                $locale
            )
        );
        return StepResult::render($response, $input->challenges);
    }

    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $tenant = $input->context->tenant;
        $username = $input->challenges->username ?? '';
        $clientId = $input->authRequest->client->id;
        $csid = (string) ($input->body['csid'] ?? '');

        $pending = $this->scopesConsent->pendingScopes($tenant, $username, $clientId, $input->authRequest->scope);
        if (!$pending) {
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $input->challenges,
                $tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $input->challenges);
        }

        [$required, $optional] = $this->splitScopes($pending);
        $requiredScopes = array_map(static fn (ScopePermission $item): string => $item->scope, $required);
        $optionalScopes = array_map(static fn (ScopePermission $item): string => $item->scope, $optional);

        $selectedOptional = $this->normalizeSelectedScopes($input->body['optional_scopes'] ?? []);
        $selectedOptional = array_values(array_intersect($selectedOptional, $optionalScopes));

        $approvedScopes = array_values(array_unique([...$requiredScopes, ...$selectedOptional]));
        if (!$approvedScopes && ($requiredScopes || $optionalScopes)) {
            throw new LoginException(auth: AuthenticationResult::scopesConsentRequired('missing_scopes_consent'));
        }

        $this->scopesConsent->storeAcceptedScopes($tenant, $username, $clientId, $approvedScopes);

        $scopeString = $this->buildScopeString($input->authRequest->scope, $approvedScopes);
        $authRequest = new AuthenticationRequest(
            client: $input->authRequest->client,
            scope: $scopeString,
            redirect: $input->authRequest->redirect,
            responseType: $input->authRequest->responseType,
            audiences: $input->authRequest->audiences
        );

        $auth = $this->authenticator->preAuthenticate(
            $authRequest,
            $input->challenges,
            $tenant,
            $input->context->issuer,
            $csid,
            $input->context->state,
            $input->context->nonce
        );
        return StepResult::proceed($auth, $input->challenges);
    }

    /**
     * @param ScopePermission[] $pending
     *
     * @return array{0: ScopePermission[], 1: ScopePermission[]}
     */
    private function splitScopes(array $pending): array
    {
        $required = [];
        $optional = [];
        foreach ($pending as $item) {
            if ($item->required) {
                $required[] = $item;
            } else {
                $optional[] = $item;
            }
        }
        return [$required, $optional];
    }

    /**
     * @param ScopePermission[] $required
     */
    private function renderRequiredBlock(string $title, array $required): string
    {
        $items = $this->renderScopeItems($required, true);
        return <<<HTML
            <section class="scopes-required">
                <ul class="scopes-list">
                    {$items}
                </ul>
            </section>
            HTML;
    }

    /**
     * @param ScopePermission[] $optional
     */
    private function renderOptionalBlock(string $title, array $optional): string
    {
        $items = $this->renderScopeItems($optional, false);

        return <<<HTML
            <section class="scopes-optional">
                <ul class="scopes-list">
                    {$items}
                </ul>
            </section>
            HTML;
    }

    /**
     * @param ScopePermission[] $permissions
     */
    private function renderScopeItems(array $permissions, bool $required): string
    {
        $items = '';
        foreach ($permissions as $permission) {
            $label = $permission->displayLabel();
            $description = $permission->description !== null && $permission->description !== '' ? $permission->description : 'Descripcion no disponible.';
            $requiredMark = $required ? ' <span class="required-marker">*</span>' : '';
            $checkbox = $required
                ? '<input type="checkbox" checked disabled />'
                : '<input type="checkbox" name="optional_scopes[]" value="' . $permission->scope . '" />';
            $items .= <<<HTML
                <li class="scope-item">
                    <label class="scope-label">
                        {$checkbox}
                        <strong>{$label}{$requiredMark}</strong>
                    </label>
                    <details class="scope-description">
                        <summary>Descripcion</summary>
                        <p>{$description}</p>
                    </details>
                </li>
                HTML;
        }
        return $items;
    }

    /**
     * @return string[]
     */
    private function normalizeSelectedScopes(mixed $values): array
    {
        if (is_string($values)) {
            $values = [$values];
        }
        if (!is_array($values)) {
            return [];
        }
        return $this->scopesConsent->normalizeScopeList($values);
    }

    /**
     * @param string[] $approvedScopes
     */
    private function buildScopeString(string $requestedScope, array $approvedScopes): string
    {
        $approvedScopes = $this->scopesConsent->normalizeScopeList($approvedScopes);
        if (!$approvedScopes) {
            return '';
        }

        $requested = $this->scopesConsent->normalizeScopes($requestedScope);
        if (!$requested) {
            return implode(' ', $approvedScopes);
        }

        $approvedSet = array_fill_keys($approvedScopes, true);
        $ordered = array_values(array_filter($requested, static fn (string $scope): bool => isset($approvedSet[$scope])));
        if (!$ordered) {
            return implode(' ', $approvedScopes);
        }
        return implode(' ', $ordered);
    }
}
